# Remediation is applicable only in certain platforms if dpkg-query --show --showformat='${db:Status-Status}' 'linux-base' 2>/dev/null | grep -q '^installed$'; then
find -P /boot/ -maxdepth 1 -perm /u+xs,g+xwrs,o+xwrt -type f -regextype posix-extended -regex '^.*System\.map.*$' -exec chmod u-xs,g-xwrs,o-xwrt {} \;
else >&2 echo 'Remediation is not applicable, nothing was done' fi

newgroup="" if getent group "adm" >/dev/null 2>&1; then newgroup="adm" elif getent group "root" >/dev/null 2>&1; then newgroup="root" fi
if [[ -z "${newgroup}" ]]; then >&2 echo "adm and root is not a defined group on the system" else find -P /var/log/ -maxdepth 1 -type f ! -group adm ! -group root -regextype posix-extended -regex '.*cloud-init\.log.*' -exec chgrp --no-dereference "$newgroup" {} \;
fi

newgroup="" if getent group "systemd-journal" >/dev/null 2>&1; then newgroup="systemd-journal" elif getent group "root" >/dev/null 2>&1; then newgroup="root" fi
if [[ -z "${newgroup}" ]]; then >&2 echo "systemd-journal and root is not a defined group on the system" else find -P /var/log/ -type f ! -group systemd-journal ! -group root -regextype posix-extended -regex '.*\.journal[~]?' -exec chgrp --no-dereference "$newgroup" {} \;
fi

